40	/// Cap on how long `step` parks while waiting for the next due token. New
41	/// submissions only drain between steps, so a full TTFT/TPOT sleep would
42	/// stall admission; 1ms keeps the CPU-only sim from spinning a core.
43	const WAIT_SLICE: Duration = Duration::from_millis(1);
44	
45	#[derive(Clone, Debug)]
46	pub struct SimulatedEngineConfig {
47	    base_ttft_ms: f64,
48	    prefill_tokens_per_ms: f64,
49	    tpot_ms: f64,
50	    fallback_token_id: u32,
51	    /// Explicit completion token-id sequence to replay verbatim. Empty (the
52	    /// default) keeps the legacy behaviour of cycling the prompt tokens.
53	    scripted_completion: Vec<u32>,
54	    /// A pretend drafter: `(K, accepted per verify step)`; `None` is no drafter.
55	    spec_decode: Option<(usize, usize)>,
56	    profile: Option<ProfileConfig>,
57	    /// A pretend prefix lookup: `(local hit tokens, externally restored hit
58	    /// tokens)` reported on each request's first chunk; `None` models an engine
59	    /// that never consults a prefix cache (disabled, or prompt scoring).
60	    prefix_cache: Option<(usize, usize)>,
61	}
62	
63	#[derive(Clone, Debug)]
64	struct ProfileConfig {
65	    profile: LoadedEngineProfile,
66	}
67	
68	impl SimulatedEngineConfig {
69	    pub fn new(
70	        base_ttft_ms: f64,
71	        prefill_tokens_per_ms: f64,
72	        tpot_ms: f64,
73	        fallback_token_id: u32,
74	    ) -> Result<Self> {
75	        ensure!(
76	            base_ttft_ms.is_finite() && base_ttft_ms >= 0.0,
77	            "base TTFT must be finite and non-negative"
78	        );
79	        ensure!(
80	            prefill_tokens_per_ms.is_finite() && prefill_tokens_per_ms > 0.0,
81	            "prefill throughput must be finite and positive"
82	        );
83	        ensure!(
84	            tpot_ms.is_finite() && tpot_ms >= 0.0,
85	            "TPOT must be finite and non-negative"
86	        );
87	
88	        Ok(Self {
89	            base_ttft_ms,
90	            prefill_tokens_per_ms,
91	            tpot_ms,
92	            fallback_token_id,
93	            scripted_completion: Vec::new(),
94	            spec_decode: None,
95	            profile: None,
96	            prefix_cache: None,
97	        })
98	    }
99	
100	    /// Make every decode step a verify step, so the metrics path has a drafter
101	    /// without a GPU or a checkpoint. Panics on a `K` past `MAX_SPEC_TOKENS`.
102	    #[must_use]
103	    pub fn with_speculative_decoding(
104	        mut self,
105	        num_spec_tokens: usize,
106	        num_accepted: usize,
107	    ) -> Self {
108	        assert!(
109	            num_accepted <= num_spec_tokens,
110	            "a verify step cannot accept more draft tokens than it proposed"
111	        );
112	        SpecDecodeCounters::new(num_spec_tokens).expect("K within MAX_SPEC_TOKENS");
113	        self.spec_decode = Some((num_spec_tokens, num_accepted));
114	        self
115	    }
116	
117	    /// Report a prefix-cache lookup on every ordinary request's first chunk:
118	    /// `hit_tokens` served from local KV and `external_hit_tokens` restored
119	    /// from the connector (CPU offload / P2P) instead. Hit 0 models a miss.
120	    #[must_use]
121	    pub fn with_prefix_cache(mut self, hit_tokens: usize, external_hit_tokens: usize) -> Self {
122	        self.prefix_cache = Some((hit_tokens, external_hit_tokens));
123	        self
124	    }
125	
126	    /// Replay `ids` verbatim as the completion for every request
127	    #[must_use]
128	    pub fn with_scripted_completion(mut self, ids: Vec<u32>) -> Self {
129	        self.scripted_completion = ids;
130	        self
131	    }
132	
133	    /// Set the token id used for empty prompts in either scheduler mode.
134	    #[must_use]
135	    pub fn with_fallback_token_id(mut self, fallback_token_id: u32) -> Self {
136	        self.fallback_token_id = fallback_token_id;
137	        self
138	    }
139	
140	    /// Use a profile bundle whose calibration manifest has already been
141	    /// validated for online step timing and scheduling.
142	    pub fn with_engine_profile(mut self, profile: LoadedEngineProfile) -> Result<Self> {
143	        profile.validate()?;
144	        self.profile = Some(ProfileConfig { profile });
145	        Ok(self)
146	    }
147	
148	    fn ttft(&self, prompt_tokens: usize) -> Result<Duration> {
149	        duration_from_ms(self.base_ttft_ms + prompt_tokens as f64 / self.prefill_tokens_per_ms)
150	    }
151	
152	    fn tpot(&self) -> Result<Duration> {
153	        duration_from_ms(self.tpot_ms)
154	    }
155	}
