261	struct SimScheduler {
262	    config: SimulatedEngineConfig,
263	    queued: Vec<QueuedRequest>,
264	    running: Vec<RunningRequest>,
265	    spec_decode: Option<SpecDecodeCounters>,
266	    profiled: Option<ProfiledRuntime>,
267	    prefix_cache: PrefixCacheTally,
268	}
