592	    fn new(config: SimulatedEngineConfig) -> Self {
593	        let spec_decode = config
594	            .spec_decode
595	            .map(|(k, _)| SpecDecodeCounters::new(k).expect("K checked at config time"));
596	        let profiled = config.profile.as_ref().map(ProfiledRuntime::new);
597	        Self {
598	            config,
599	            queued: Vec::new(),
600	            running: Vec::new(),
601	            spec_decode,
602	            profiled,
603	            prefix_cache: PrefixCacheTally::default(),
604	        }
605	    }
